content = TI.read_text(encoding="utf-8")
# Detect frontmatter at top (lines starting with ---\n...\n---\n)
lines = content.split("\n")
fm_end = -1
if lines and lines[0] == "---":
    # find closing ---
    for i in range(1, len(lines)):
        if lines[i] == "---":
            fm_end = i
            break

if fm_end == -1:
    # No frontmatter, prepend NEW
    new_content = NEW + content.lstrip("\n")
else:
    fm_block = "\n".join(lines[:fm_end+1]) + "\n"
    body = "\n".join(lines[fm_end+1:])
    # Find first ## in body
    idx = body.find("\n## ")
    if idx == -1:
        new_content = fm_block + "\n" + NEW + body.lstrip("\n")
    else:
        # idx points at the \n just before "## "
        new_content = fm_block + body[:idx+1] + "\n" + NEW + body[idx+1:].lstrip("\n")

TI.write_text(new_content, encoding="utf-8")
print(f"Updated {TI} ({len(new_content)} bytes)")